CREATE TABLE org_units(code TEXT PRIMARY KEY,name TEXT NOT NULL,unit_type TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,verification TEXT NOT NULL DEFAULT 'unverified',source TEXT NOT NULL DEFAULT 'Reference/AICTE_Dashboard_Reference_Spec.md');
ALTER TABLE tags ADD COLUMN active INTEGER NOT NULL DEFAULT 1;
ALTER TABLE tags ADD COLUMN source TEXT NOT NULL DEFAULT 'Reference/AICTE_Dashboard_Reference_Spec.md';
