UPDATE cases SET tags=(SELECT json_group_array(CASE value WHEN 'fees' THEN 'FEE_EXCESS' WHEN 'refund' THEN 'FEE_REFUND' WHEN 'approval' THEN 'APPROVAL_IRREGULARITY' WHEN 'faculty' THEN 'FACULTY_SHORTAGE' WHEN 'facilities' THEN 'INFRASTRUCTURE_DEFICIT' WHEN 'admission' THEN 'ADM_PROCESS' ELSE value END) FROM json_each(cases.tags));
UPDATE tags SET active=0 WHERE code IN('fees','refund','approval','faculty','facilities','admission');
UPDATE officials SET bureau=CASE bureau WHEN 'Regulation' THEN 'RB' WHEN 'Grievance' THEN 'PGRC' ELSE bureau END;
UPDATE cases SET bureau=CASE bureau WHEN 'Regulation' THEN 'RB' WHEN 'Grievance' THEN 'PGRC' ELSE bureau END;
UPDATE coordination_requests SET target_bureau=CASE target_bureau WHEN 'Regulation' THEN 'RB' WHEN 'Grievance' THEN 'PGRC' ELSE target_bureau END;
UPDATE institutions SET region=CASE region WHEN 'West' THEN 'Western' WHEN 'South' THEN 'Southern' WHEN 'North' THEN 'Northern' ELSE region END;
